sys_ui_action.client_script_v2:
function onClick(g_form) {

    //check if form has unsaved changes
    if (g_form.isModified()) {
        g_form.save().then(function() {
            //after save completes, trigger again
            g_form.submit('submit_project_package');
        });
    } else {
        //if already saved, just submit
        g_form.submit('submit_project_package');
    }
}

sys_ui_action.script:
(function executeAction(current, previous) {

    var gr = new GlideRecord(current.getTableName());
    if (!gr.get(current.sys_id)) {
        gs.addErrorMessage('Unable to load Project Package.');
        current.setAbortAction(true);
        return;
    }

    // Hard guard from DB state
    if (gr.u_submission_in_progress == true) {
        gs.addInfoMessage('Submission already in progress.');
        current.setAbortAction(true);
        return;
    }

    if (gr.u_submission_state != 'Draft' && gr.u_submission_state != 'Returned') {
        gs.addInfoMessage('This Project Package is not in a submittable state.');
        current.setAbortAction(true);
        return;
    }

    var user = gs.getUser();
    var userId = gs.getUserID();

    // Lock first
    gr.u_submission_in_progress = true;

    // Stamp submit metadata
    gr.u_submitter = userId;

    if (user.isMemberOf('AMP OMI Representatives')) {
        gr.u_submission_type = 'OMI Representative';
    } else if (user.isMemberOf('AMP FMC Representatives')) {
        gr.u_submission_type = 'FMC Representative';
    } else {
        gr.u_submission_type = 'Site Representative';
    }

    // Move into flow trigger state
    gr.u_submission_state = 'Submitted';
    gr.update();

    gs.addInfoMessage('Project Package submitted for approval.');
    action.setRedirectURL(gr);

})(current, previous);
